mapper.insert:
insert into user_notification (
    notification_id, recipient_id, actor_id, event_id, dedupe_key, type,
    solution_id, comment_id, action, reason, occurred_at, created_at, read_at
) values (
    #{notification.notificationId}, #{notification.recipientId}, #{notification.actorId},
    #{notification.eventId}, #{notification.dedupeKey}, #{notification.type},
    #{notification.solutionId}, #{notification.commentId}, #{notification.action},
    #{notification.reason}, #{notification.occurredAt}, #{notification.createdAt}, #{notification.readAt}
)

mapper.select:
select notification_id
from user_notification
where recipient_id = #{recipientId}
  and dedupe_key = #{dedupeKey}
limit 1
for update

select notification_id, recipient_id, actor_id, event_id, dedupe_key, type, solution_id, comment_id, action, reason, occurred_at, created_at, read_at from user_notification where recipient_id = #{recipientId}
and read_at is null
order by notification_id desc limit #{offset}, #{pageSize}

select count(*)
from user_notification
where recipient_id = #{recipientId}
  and notification_id = #{notificationId}

mapper.update:
update user_notification
set read_at = #{readAt}
where notification_id = #{notificationId}
  and recipient_id = #{recipientId}
  and read_at is null

update user_notification
set read_at = #{readAt}
where recipient_id = #{recipientId}
  and notification_id <= #{throughId}
  and read_at is null

mapper.delete:
delete from user_notification
where created_at < #{createdBefore}
order by created_at asc, notification_id asc
limit #{limit}
